const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={done:[],notes:{},last:'tensor'};try{const saved=JSON.parse(localStorage.getItem('visionlab-state'));if(saved&&Array.isArray(saved.done)&&saved.notes&&typeof saved.notes==='object')state={...state,...saved};}catch{}
let filter='all', query='';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400)}
function save(){try{localStorage.setItem('visionlab-state',JSON.stringify(state));return true}catch{toast('浏览器无法保存数据，请允许本站存储。');return false}}
function networkArt(big=false){return `<svg viewBox="0 0 420 250" fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="从图像特征到检测框的神经网络示意"><defs><pattern id="grid${big}" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M18 0H0V18" stroke="#d4cce9" stroke-width=".5"/></pattern></defs><rect x="15" y="10" width="390" height="230" rx="12" fill="url(#grid${big})"/><g stroke="#b8aadf" stroke-width="1" opacity=".7">${[55,100,145,190].flatMap(y=>[45,85,125,165,205].map(z=>`<path d="M92 ${y}L188 ${z}"/>`)).join('')}${[45,85,125,165,205].flatMap(y=>[70,125,180].map(z=>`<path d="M188 ${y}L283 ${z}"/>`)).join('')}<path d="M283 70L350 125M283 125H350M283 180L350 125"/></g><g fill="#fff" stroke="#9783ce" stroke-width="2">${[55,100,145,190].map(y=>`<circle cx="92" cy="${y}" r="8"/>`).join('')}${[45,85,125,165,205].map(y=>`<circle cx="188" cy="${y}" r="10" fill="#d4c9ed"/>`).join('')}${[70,125,180].map(y=>`<circle cx="283" cy="${y}" r="10" fill="#b39fde"/>`).join('')}<rect x="332" y="104" width="42" height="42" rx="9" fill="#7662bd"/></g><path d="M343 117H363V135H343Z" stroke="white" stroke-dasharray="3 2"/><g font-family="Segoe UI,sans-serif" fill="#9183aa" font-size="9" letter-spacing="1"><text x="64" y="232">INPUT</text><text x="158" y="232">FEATURES</text><text x="263" y="232">FUSION</text><text x="330" y="167">DETECT</text></g><rect x="255" y="15" width="140" height="26" rx="6" fill="#ffffffb0"/><circle cx="269" cy="28" r="3" fill="#7f6ac7"/><text x="279" y="31" font-family="monospace" font-size="9" fill="#8976b3">learning in progress</text></svg>`}
function art(g){if(g==='dl')return networkArt();if(g==='cv')return `<svg viewBox="0 0 330 140" fill="none" role="img" aria-label="卷积核提取图像特征示意"><g transform="translate(52 22) rotate(-8 45 45)"><rect width="85" height="85" rx="4" fill="#cbdcf0"/>${Array.from({length:25},(_,i)=>`<rect x="${i%5*15+6}" y="${Math.floor(i/5)*15+6}" width="12" height="12" rx="1" fill="${['#83a7d1','#a6bfdd','#dce8f5'][i%3]}"/>`).join('')}<rect x="19" y="19" width="47" height="47" stroke="#628ccc" stroke-width="2"/></g><path d="M157 65H188M181 59L188 65L181 71" stroke="#89a5ca" stroke-width="2"/><rect x="210" y="25" width="66" height="80" rx="4" fill="#c8d8ed"/><rect x="220" y="35" width="66" height="80" rx="4" fill="#afc6e3"/><rect x="230" y="45" width="66" height="80" rx="4" fill="#92b1d6"/><path d="M240 65H285M240 80H285M240 95H285" stroke="#dce9f8" stroke-width="6"/></svg>`;return `<svg viewBox="0 0 330 140" fill="none" role="img" aria-label="目标检测示意图"><rect x="52" y="15" width="226" height="115" rx="5" fill="#daeae4"/><path d="M53 109L98 68L131 85L187 42L278 101V130H52Z" fill="#c1d9cf"/><rect x="104" y="40" width="24" height="55" rx="5" fill="#9dbdae"/><circle cx="116" cy="34" r="9" fill="#9dbdae"/><rect x="91" y="18" width="50" height="89" rx="2" stroke="#419f87" stroke-width="1.5"/><rect x="91" y="9" width="66" height="16" rx="2" fill="#419f87"/><text x="97" y="20" font-family="monospace" font-size="8" fill="white">person 0.96</text><rect x="180" y="75" width="58" height="28" rx="7" fill="#99bbaa"/><circle cx="191" cy="105" r="6" fill="#81a797"/><circle cx="226" cy="105" r="6" fill="#81a797"/><rect x="171" y="62" width="75" height="55" rx="2" stroke="#76ab78" stroke-width="1.5"/><rect x="171" y="49" width="54" height="15" rx="2" fill="#76ab78"/><text x="177" y="60" font-family="monospace" font-size="8" fill="white">car 0.91</text></svg>`}
function card(l){return `<a class="course-card" href="#lesson/${l.id}"><div class="card-art ${l.group}"><span class="card-label">${groups[l.group].label}</span>${art(l.group)}</div><div class="card-body"><span class="tag ${l.group}">${groups[l.group].name} · ${l.level}</span><h3>${l.title}</h3><p>${l.desc}</p><div class="card-meta"><span>◷ ${l.time} 分钟 · 理论 + 代码</span><b>${state.done.includes(l.id)?'已完成 ✓':'开始学习 ↗'}</b></div></div></a>`}
function filters(){return `<div class="filters">${[['all','全部内容'],['dl','深度学习'],['cv','计算机视觉'],['yolo','YOLOv5 实战']].map(([id,name])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}">${name}</button>`).join('')}</div>`}
function matched(){return lessons.filter(l=>(filter==='all'||l.group===filter)&&(!query||JSON.stringify(l).toLowerCase().includes(query.toLowerCase())))}
function grid(home=false){const found=matched();return `<div class="course-grid">${found.length?(home?found.slice(0,4):found).map(card).join(''):'<div class="empty">没有找到相关课程。试试“卷积”“训练”或“YOLO”。</div>'}</div>`}
function heading(title,sub,eyebrow='YOUR LEARNING SPACE'){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="subtitle">${sub}</p></div><span class="date-pill">◷ 按自己的节奏，持续进步</span></div>`}
function home(){const percent=Math.round(state.done.length/lessons.length*100);const next=lessons.find(l=>l.id===state.last&&!state.done.includes(l.id))||lessons.find(l=>!state.done.includes(l.id))||lessons[0];return `${heading('每一次理解，都是一次进步。','欢迎来到 VisionLab，开始今天的探索吧。')}<section class="hero"><div class="hero-copy"><div class="eyebrow">FROM PIXELS TO POSSIBILITIES</div><h2>让机器看懂世界，<br><span>从这里开始。</span></h2><p>连接理论与代码，探索深度学习的底层逻辑。<br>从第一个张量，到属于你的 YOLOv5 检测模型。</p><a href="#lesson/${next.id}" class="primary">${state.done.length?'继续学习':'开启学习之旅'} <span>→</span></a><a href="#path" class="text-button">查看学习路线 ↗</a></div><div class="hero-art">${networkArt(true)}</div></section><div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><small>系统学习内容</small><strong>12 <em>节精选课程</em></strong></div></div><div class="stat"><span class="stat-icon">✓</span><div><small>我的学习进度</small><strong>${state.done.length} <em>/ 12 节已完成</em></strong></div></div><div class="stat"><span class="stat-icon">▧</span><div><small>记录你的思考</small><strong>${Object.values(state.notes).filter(n=>n.trim()).length} <em>篇学习笔记</em></strong></div></div></div><div class="home-grid"><section><div class="section-title"><h2>探索学习内容</h2><a href="#courses">查看全部课程 →</a></div>${filters()}${grid(true)}</section><aside class="right-column"><div class="side-panel"><h3>我的学习进度</h3><div class="progress-ring"><div class="ring" style="--progress:${percent}%"><span>${percent}%</span></div><div><b>${state.done.length?'保持探索的节奏':'从第一课开始'}</b><small>已完成 ${state.done.length} / 12 节课程</small></div></div>${Object.entries(groups).map(([key,g])=>{const n=lessons.filter(l=>l.group===key&&state.done.includes(l.id)).length;return `<div class="progress-row"><span>${g.name}</span><span>${n}/4</span></div><div class="progress-bar"><i style="width:${n*25}%"></i></div>`}).join('')}</div><div class="side-panel"><div class="section-title"><h3 style="margin:0">推荐学习路线</h3><a href="#path">↗</a></div>${Object.entries(groups).map(([key,g],i)=>`<a href="#courses/${key}" class="path-step"><span class="step-number">0${i+1}</span><div><b>${g.name}</b><small>${['张量 · 梯度 · 神经网络','图像 · 卷积 · 检测指标','结构 · 数据 · 训练部署'][i]}</small></div></a>`).join('')}</div><div class="side-panel mini-callout"><h3>⌬ 让概念动起来</h3><p>移动预测框，亲手感受 IoU 的变化。</p><a href="#lab">进入交互实验室 →</a></div></aside></div>`}
function courses(){return heading(query?`搜索“${esc(query)}”`:'选择你的下一次探索','每节课程，都从一个问题出发。','COURSE LIBRARY')+filters()+`<p class="result-caption">${matched().length} 节课程 · 代码可复制到本地运行</p>`+grid()}
function path(){return heading('从基础出发，走向实战。','建议按阶段学习，也可以直接进入你感兴趣的章节。','LEARNING ROADMAP')+Object.entries(groups).map(([key,g],i)=>`<section class="route-block"><span class="eyebrow">STAGE 0${i+1} · ${g.label}</span><h2>${g.name}</h2><p>${g.desc}</p><div class="route-lessons">${lessons.filter(l=>l.group===key).map(l=>`<a href="#lesson/${l.id}">${state.done.includes(l.id)?'✓':'○'} ${l.title} <span style="float:right;color:var(--muted)">${l.time} 分钟 →</span></a>`).join('')}</div></section>`).join('')+`<div class="callout">实践目标：准备自己的检测数据集，完成一次小规模训练，对新图像推理，并记录错误样本与评估指标。</div>`}
function lesson(id){const l=lessons.find(l=>l.id===id);if(!l)return '<div class="empty">课程不存在。<a href="#courses">返回课程列表</a></div>';state.last=id;save();const next=lessons[lessons.indexOf(l)+1];return `<article class="article"><a class="tag" href="#courses/${l.group}">← ${groups[l.group].name}</a><div class="article-header"><span class="eyebrow">${groups[l.group].label} · ${l.level}</span><h1>${l.title}</h1><p class="subtitle">${l.desc}</p><p class="subtitle">◷ 约 ${l.time} 分钟 · 理论 / 实践 / 自测</p></div><div class="article-content">${l.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<div class="code-block"><div class="code-head"><span>${l.language||'Python'} · 可复制示例</span><button class="copy" data-copy="${l.id}">复制代码</button></div><pre>${esc(l.code)}</pre></div><div class="callout">代码需在本地配置好的 Python / YOLOv5 环境运行。${l.group==='yolo'?'本课采用 YOLOv5 仓库的脚本接口，数据与权重路径需按实际项目调整。':'先运行并观察形状或输出，再尝试改变一个参数。'}</div>${l.id==='iou'?'<a class="primary" href="#lab">进入 IoU 交互实验 →</a>':''}<div class="quiz"><h3>检查一下你的理解</h3><p>${l.quiz.q}</p>${l.quiz.options.map((o,i)=>`<button data-answer="${i}" data-lesson="${l.id}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<div class="quiz-result" aria-live="polite"></div></div><h2>写下你的思考</h2><p class="subtitle">笔记与学习进度保存在当前浏览器。清除网站数据会删除记录。</p><textarea class="note-input" id="lesson-note" placeholder="今天理解了什么？还有哪些疑问？" aria-label="课程笔记">${esc(state.notes[id]||'')}</textarea><div class="lesson-actions"><button class="secondary" data-save-note="${id}">保存笔记</button><span id="note-status" class="saved" role="status"></span></div><div class="lesson-actions"><button class="primary" data-complete="${id}">${state.done.includes(id)?'已完成 · 点击撤销':'标记为已完成 ✓'}</button>${next?`<a class="secondary" href="#lesson/${next.id}">下一课 →</a>`:'<a class="secondary" href="#path">回顾学习路线 →</a>'}</div></div></article>`}
function notes(){const items=lessons.filter(l=>(state.notes[l.id]||'').trim());return heading('把理解，留给未来的自己。','集中回顾课程中的思考与问题。笔记保存在当前浏览器。','MY NOTEBOOK')+(items.length?`<button class="secondary" id="export-notes">导出全部笔记 ↓</button>`+items.map(l=>`<div class="notes-card"><a href="#lesson/${l.id}"><h3>${l.title} ↗</h3></a><p>${esc(state.notes[l.id])}</p><button class="secondary" data-delete-note="${l.id}">删除此笔记</button></div>`).join(''):'<div class="empty">还没有笔记。在课程页面写下你的第一个发现。<br><a href="#courses">去学习并记录 →</a></div>')}
function lab(){return heading('让抽象概念，变得直观。','移动预测框，看一看交并比如何变化。','INTERACTIVE LAB')+`<div class="lab-grid"><section class="lab-canvas"><svg viewBox="0 0 420 300" role="img" aria-label="真实框与可移动预测框"><defs><pattern id="labgrid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" stroke="#e5e5ef" stroke-width=".7"/></pattern></defs><rect width="420" height="300" fill="url(#labgrid)"/><rect x="90" y="80" width="150" height="120" fill="#4d9f8b22" stroke="#409c88" stroke-width="2"/><text x="90" y="72" fill="#409c88" font-size="11">真实框 Ground truth</text><rect id="prediction-box" x="140" y="110" width="150" height="120" fill="#7661ce30" stroke="#7661ce" stroke-width="2"/><text id="prediction-label" x="140" y="248" fill="#7661ce" font-size="11">预测框 Prediction</text></svg><label>水平位置 <span id="x-label">140</span><input id="box-x" type="range" min="0" max="270" value="140"></label><label>垂直位置 <span id="y-label">110</span><input id="box-y" type="range" min="25" max="180" value="110"></label><button id="reset-box" class="secondary">重置位置</button><button id="align-box" class="secondary">完全重合</button></section><section class="lab-canvas"><span class="eyebrow">INTERSECTION OVER UNION</span><div class="iou-value" id="iou-value">0.333</div><h3>IoU = 交集面积 / 并集面积</h3><p id="iou-detail" class="subtitle"></p><div class="callout">绿色框代表真实标注，紫色框代表预测。两者越重合，IoU 越接近 1。</div><p>试着把两个框分开，再让它们完全重合。这里固定了框的尺寸，因此只改变位置。</p><p class="subtitle">这是一项几何教学实验，未在浏览器运行目标检测模型。</p><a href="#lesson/iou" class="primary" style="margin-top:22px">学习边界框与 IoU →</a></section></div>`}
function updateIoU(){const x=+$('#box-x').value,y=+$('#box-y').value,w=Math.max(0,Math.min(240,x+150)-Math.max(90,x)),h=Math.max(0,Math.min(200,y+120)-Math.max(80,y)),inter=w*h,union=36000-inter;$('#prediction-box').setAttribute('x',x);$('#prediction-box').setAttribute('y',y);$('#prediction-label').setAttribute('x',x);$('#prediction-label').setAttribute('y',Math.min(294,y+137));$('#x-label').textContent=x;$('#y-label').textContent=y;$('#iou-value').textContent=(inter/union).toFixed(3);$('#iou-detail').textContent=`交集 ${inter.toLocaleString()} · 并集 ${union.toLocaleString()} 平方单位`}
function resources(){const links=[['PyTorch 官方基础教程','张量、自动求导、模型构建与训练循环。','https://docs.pytorch.org/tutorials/beginner/basics/intro.html','PyTorch'],['YOLOv5 自定义数据训练','数据集准备与仓库脚本训练接口。','https://docs.ultralytics.com/zh/yolov5/tutorials/train-custom-data/','Ultralytics'],['YOLOv5 官方源代码','结合 models、utils、train.py 与 detect.py 阅读实现。','https://github.com/ultralytics/yolov5','GitHub · Ultralytics'],['YOLOv5 模型导出','ONNX 等导出格式的配置与注意事项。','https://docs.ultralytics.com/yolov5/tutorials/model-export/','Ultralytics'],['Dive into Deep Learning','开放的深度学习教材，补充数学与算法基础。','https://zh.d2l.ai/','动手学深度学习']];return heading('好的资料，让探索更深入。','先完成一段学习，再带着问题去阅读原始文档。','RESOURCE LIBRARY')+links.map(([title,desc,url,from])=>`<a class="resource" href="${url}" target="_blank" rel="noopener noreferrer"><strong>${title} ↗</strong><p>${desc}</p><small>${from}</small></a>`).join('')+`<div class="callout">内容核对：2026 年 10 月 13 日。YOLOv5 实战结合当前工作区的 C3 / SPPF 配置编写；官方接口与依赖可能随版本变化。本站提供课程与示例，实际训练在你的本地环境完成。</div>`}
function render(){const [rawRoute,id]=location.hash.slice(1).split('/');const route=rawRoute||'home';if(route==='courses'&&id&&groups[id])filter=id;const titles={home:'学习概览',courses:'全部课程',path:'学习路线',lab:'交互实验室',notes:'我的笔记',resources:'资源导航',lesson:'课程阅读'};$('#crumb').textContent=titles[route]||'学习概览';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(route==='lesson'?'courses':route)));$('#content').innerHTML=({home,courses,path,lab,notes,resources}[route]||(()=>lesson(id)))();if(route==='lab')updateIoU();$('.sidebar').classList.remove('open');document.title=`${titles[route]||'课程阅读'} · VisionLab`;}
window.addEventListener('hashchange',()=>{window.render();window.scrollTo(0,0)});
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.matches('.mobile-menu')){$('.sidebar').classList.toggle('open');return}if(t.dataset.filter){filter=t.dataset.filter;window.render()}if(t.dataset.copy){try{await navigator.clipboard.writeText(lessons.find(l=>l.id===t.dataset.copy).code);toast('代码已复制')}catch{toast('复制失败，请选中代码后手动复制。')}}if(t.dataset.exerciseAnswer!==undefined||t.dataset.answer!==undefined){const l=lessons.find(l=>l.id===t.dataset.lesson),legacy=t.dataset.exerciseAnswer===undefined,exercise=legacy?l.quiz:(t.dataset.exerciseType==='section'?l.sections[+t.dataset.sectionIndex].exercise:l.chapterExercises[+t.dataset.exerciseIndex]),selected=+(legacy?t.dataset.answer:t.dataset.exerciseAnswer),correct=selected===exercise.answer,card=t.closest('.exercise-card')||t.closest('.quiz');card.querySelectorAll('button').forEach(b=>b.classList.remove('correct','wrong'));t.classList.add(correct?'correct':'wrong');card.querySelector('.quiz-result').textContent=(correct?'回答正确。':'再想一想。正确答案：'+String.fromCharCode(65+exercise.answer)+'。')+'解析：'+exercise.why}if(t.dataset.saveNote){state.notes[t.dataset.saveNote]=$('#lesson-note').value;if(save())$('#note-status').textContent='笔记已保存'}if(t.dataset.complete){const id=t.dataset.complete;if($('#lesson-note').value.trim())state.notes[id]=$('#lesson-note').value;state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();window.render();toast(state.done.includes(id)?'已记录这次进步 ✓':'已撤销完成标记')}if(t.dataset.deleteNote){delete state.notes[t.dataset.deleteNote];save();window.render();toast('笔记已删除')}if(t.id==='reset-box'||t.id==='align-box'){$('#box-x').value=t.id==='align-box'?90:140;$('#box-y').value=t.id==='align-box'?80:110;updateIoU()}if(t.id==='export-notes'){const txt=lessons.filter(l=>state.notes[l.id]).map(l=>`# ${l.title}\n\n${state.notes[l.id]}`).join('\n\n---\n\n'),url=URL.createObjectURL(new Blob([txt],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='VisionLab-学习笔记.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
$('#search').addEventListener('input',e=>{query=e.target.value.trim();filter='all';if(location.hash!=='#courses')location.hash='courses';else window.render()});document.addEventListener('input',e=>{if(e.target.id==='box-x'||e.target.id==='box-y')updateIoU();if(e.target.id==='lesson-note')$('#note-status').textContent='尚未保存'});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape')$('.sidebar').classList.remove('open')});
// textbook-ui-v3.js renders after course data and interactive modules are ready.
